#include <bits/stdc++.h>
using namespace std;using E=pair<int,int>;int n,m;vector<E>ed;
static bool conn(const vector<int>&a,uint64_t mask){uint16_t inf[10];for(int i=0;i<n;i++)inf[i]=1<<i;for(int j=0;j<m;j++)if((mask>>j)&1){auto[u,v]=ed[a[j]];inf[u]|=inf[v];inf[v]=inf[u];}int all=(1<<n)-1;for(int i=0;i<n;i++)if(inf[i]!=all)return false;return true;}
static bool pivot(const vector<int>&a){uint16_t pre[10],fut[10],suff[45];for(int i=0;i<n;i++)pre[i]=fut[i]=1<<i;for(int i=m-1;i>=0;i--){auto [u,v]=ed[a[i]];suff[i]=fut[u]|fut[v];fut[u]=fut[v]=suff[i];}int all=(1<<n)-1;for(int i=0;i<m;i++){auto[u,v]=ed[a[i]];if((pre[u]|pre[v])==all&&suff[i]==all)return true;pre[u]|=pre[v];pre[v]=pre[u];}return false;}
static int forced(const vector<int>&a){uint64_t full=(1ull<<m)-1;int cnt=0;for(int i=0;i<m;i++)cnt+=!conn(a,full^(1ull<<i));return cnt;}
int main(int argc,char**argv){n=atoi(argv[1]);int limit=argc>2?atoi(argv[2]):50000;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)ed.push_back({i,j});m=ed.size();vector<int>a(m);iota(a.begin(),a.end(),0);mt19937 rng(27174+n);long long np=0;int best=0;array<long long,46>hist{};bool exhaustive=(n<=5);long long total=0;do{total++;if(!pivot(a)){np++;int f=forced(a);hist[f]++;best=max(best,f);}if(exhaustive){if(!next_permutation(a.begin(),a.end()))break;}else{if(total>=limit)break;shuffle(a.begin(),a.end(),rng);}}while(true);cout<<"n="<<n<<" tested="<<total<<" nonpivot="<<np<<" maxforced="<<best<<" histogram:";for(int i=0;i<=m;i++)if(hist[i])cout<<" "<<i<<":"<<hist[i];cout<<"\n";}
